import sqlite3
from datetime import datetime, timedelta
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont
import seed_dev_library as seed

# All titles are public domain in the US and Germany; the sample EPUB bodies
# generated by seed_dev_library are synthetic and are not the actual books.
